import{_ as l,a as r,e as t,l as a,ar as o,O as n,t as s}from"./chunks/framework.CK3qJuPR.js";const m=JSON.parse('{"title":"浏览器原理","description":"","frontmatter":{"title":"浏览器原理","tags":["interview","browser"]},"headers":[],"relativePath":"interview/02-Browser.md","filePath":"interview/02-Browser.md","lastUpdated":1761045430000}'),d={name:"interview/02-Browser.md"},h={id:"frontmatter-title",tabindex:"-1"};function c(i,e,p,b,u,g){return t(),r("div",null,[e[1]||(e[1]=a("div",{style:{display:"none"},hidden:"true","aria-hidden":"true"},"Are you an LLM? You can read better optimized documentation at /vite-press/interview/02-Browser.md for this page in Markdown format",-1)),a("h1",h,[n(s(i.$frontmatter.title)+" ",1),e[0]||(e[0]=a("a",{class:"header-anchor",href:"#frontmatter-title","aria-label":"Permalink to “{{ $frontmatter.title }}”"},"​",-1))]),e[2]||(e[2]=o(`<h2 id="🧠-一、浏览器工作原理" tabindex="-1">🧠 一、浏览器工作原理 <a class="header-anchor" href="#🧠-一、浏览器工作原理" aria-label="Permalink to “🧠 一、浏览器工作原理”">​</a></h2><h3 id="_1-浏览器从输入-url-到页面展示的全过程" tabindex="-1">1. 浏览器从输入 URL 到页面展示的全过程？ <a class="header-anchor" href="#_1-浏览器从输入-url-到页面展示的全过程" aria-label="Permalink to “1. 浏览器从输入 URL 到页面展示的全过程？”">​</a></h3><p><strong>答题要点：</strong></p><ul><li><p>DNS 解析 → TCP 连接（三次握手）→ 发送 HTTP 请求 → 服务器响应 → 浏览器接收响应 → 渲染页面</p></li><li><p>渲染过程：</p><ul><li>解析 HTML → 构建 DOM</li><li>解析 CSS → 构建 CSSOM</li><li>DOM + CSSOM → Render Tree</li><li>Layout（计算位置）→ Painting（绘制）→ Compositing（合成层）</li></ul></li></ul><h3 id="_2-浏览器内核有哪些-有哪些区别" tabindex="-1">2. 浏览器内核有哪些？有哪些区别？ <a class="header-anchor" href="#_2-浏览器内核有哪些-有哪些区别" aria-label="Permalink to “2. 浏览器内核有哪些？有哪些区别？”">​</a></h3><p><strong>答题要点：</strong></p><ul><li><p>常见内核：</p><ul><li>Blink（Chrome、Edge）</li><li>WebKit（Safari）</li><li>Gecko（Firefox）</li></ul></li><li><p>区别：</p><ul><li>渲染机制不同</li><li>兼容性表现不同</li><li>API 实现略有差异</li></ul></li></ul><h3 id="_3-浏览器的多进程与多线程模型" tabindex="-1">3. 浏览器的多进程与多线程模型？ <a class="header-anchor" href="#_3-浏览器的多进程与多线程模型" aria-label="Permalink to “3. 浏览器的多进程与多线程模型？”">​</a></h3><p><strong>答题要点：</strong></p><ul><li><p>一个标签页对应一个进程（隔离性高）</p></li><li><p>渲染进程内是多线程的：</p><ul><li>GUI 渲染线程</li><li>JS 引擎线程（互斥）</li><li>事件触发线程</li><li>定时器线程</li><li>网络线程等</li></ul></li></ul><h2 id="⏱-二、性能优化" tabindex="-1">⏱ 二、性能优化 <a class="header-anchor" href="#⏱-二、性能优化" aria-label="Permalink to “⏱ 二、性能优化”">​</a></h2><h3 id="_4-如何优化首次加载性能-白屏时间" tabindex="-1">4. 如何优化首次加载性能（白屏时间）？ <a class="header-anchor" href="#_4-如何优化首次加载性能-白屏时间" aria-label="Permalink to “4. 如何优化首次加载性能（白屏时间）？”">​</a></h3><p><strong>答题要点：</strong></p><ul><li>资源压缩（JS/CSS/图片）</li><li>懒加载（图片、组件、模块）</li><li>SSR 或预渲染</li><li>CDN 加速</li><li>优化关键渲染路径（Critical CSS、defer/async）</li></ul><h3 id="_5-什么是关键渲染路径-critical-rendering-path" tabindex="-1">5. 什么是关键渲染路径（Critical Rendering Path）？ <a class="header-anchor" href="#_5-什么是关键渲染路径-critical-rendering-path" aria-label="Permalink to “5. 什么是关键渲染路径（Critical Rendering Path）？”">​</a></h3><p><strong>答题要点：</strong></p><ul><li><p>浏览器将 HTML、CSS、JS 转化为像素的流程</p></li><li><p>关键阶段包括：</p><ul><li>DOM 构建</li><li>CSSOM 构建</li><li>Render Tree 构建</li><li>Layout</li><li>Paint</li><li>Composite</li></ul></li></ul><h2 id="🔐-三、安全相关" tabindex="-1">🔐 三、安全相关 <a class="header-anchor" href="#🔐-三、安全相关" aria-label="Permalink to “🔐 三、安全相关”">​</a></h2><h3 id="_6-常见的前端安全问题有哪些-如何防御" tabindex="-1">6. 常见的前端安全问题有哪些？如何防御？ <a class="header-anchor" href="#_6-常见的前端安全问题有哪些-如何防御" aria-label="Permalink to “6. 常见的前端安全问题有哪些？如何防御？”">​</a></h3><p><strong>答题要点：</strong></p><ul><li>XSS（跨站脚本攻击）：输出时转义、使用 CSP、避免 innerHTML</li><li>CSRF（跨站请求伪造）：使用 Token 校验、SameSite Cookie、Referer 校验</li><li>点击劫持：使用 <code>X-Frame-Options</code>，设置 CSP frame-ancestors</li><li>内容劫持：设置 <code>Content-Security-Policy</code>、避免开放上传</li></ul><h3 id="_7-什么是-samesite-cookie-有哪些值" tabindex="-1">7. 什么是 SameSite Cookie？有哪些值？ <a class="header-anchor" href="#_7-什么是-samesite-cookie-有哪些值" aria-label="Permalink to “7. 什么是 SameSite Cookie？有哪些值？”">​</a></h3><p><strong>答题要点：</strong></p><ul><li><p>用于限制第三方 Cookie 发送</p></li><li><p>可选值：</p><ul><li>Strict：完全禁止跨站发送</li><li>Lax：部分允许（GET 请求）</li><li>None：允许第三方发送，需 <code>Secure</code> 配合</li></ul></li></ul><h2 id="📆-四、浏览器存储" tabindex="-1">📆 四、浏览器存储 <a class="header-anchor" href="#📆-四、浏览器存储" aria-label="Permalink to “📆 四、浏览器存储”">​</a></h2><h3 id="_8-localstorage、sessionstorage、cookie-的区别" tabindex="-1">8. localStorage、sessionStorage、cookie 的区别？ <a class="header-anchor" href="#_8-localstorage、sessionstorage、cookie-的区别" aria-label="Permalink to “8. localStorage、sessionStorage、cookie 的区别？”">​</a></h3><table tabindex="0"><thead><tr><th>特性</th><th>localStorage</th><th>sessionStorage</th><th>cookie</th></tr></thead><tbody><tr><td>生命周期</td><td>永久（除非手动清除）</td><td>会话级别</td><td>可设置过期时间</td></tr><tr><td>大小限制</td><td>~5MB</td><td>~5MB</td><td>~4KB</td></tr><tr><td>是否随请求发送</td><td>否</td><td>否</td><td>是（自动发送）</td></tr><tr><td>使用场景</td><td>本地持久化</td><td>页面会话数据</td><td>登录状态、跨域验证</td></tr></tbody></table><h3 id="_9-indexeddb-和-localstorage-区别" tabindex="-1">9. IndexedDB 和 localStorage 区别？ <a class="header-anchor" href="#_9-indexeddb-和-localstorage-区别" aria-label="Permalink to “9. IndexedDB 和 localStorage 区别？”">​</a></h3><p><strong>答题要点：</strong></p><ul><li>IndexedDB 是一个异步、支持对象存储的数据库</li><li>localStorage 是同步的，字符串存储</li><li>IndexedDB 适合大型数据、复杂结构、异步场景</li></ul><h2 id="📤-五、事件机制" tabindex="-1">📤 五、事件机制 <a class="header-anchor" href="#📤-五、事件机制" aria-label="Permalink to “📤 五、事件机制”">​</a></h2><h3 id="_10-浏览器中的事件循环-event-loop-机制" tabindex="-1">10. 浏览器中的事件循环（Event Loop）机制？ <a class="header-anchor" href="#_10-浏览器中的事件循环-event-loop-机制" aria-label="Permalink to “10. 浏览器中的事件循环（Event Loop）机制？”">​</a></h3><p><strong>答题要点：</strong></p><ul><li>主线程处理调用堆</li><li>执行宏任务（如：setTimeout、事件回调）和微任务（Promise.then、MutationObserver）</li><li>每个宏任务执行完 → 执行所有微任务 → 才进入下一个宏任务</li></ul><h3 id="_11-什么是事件捕获与事件冒泡" tabindex="-1">11. 什么是事件捕获与事件冒泡？ <a class="header-anchor" href="#_11-什么是事件捕获与事件冒泡" aria-label="Permalink to “11. 什么是事件捕获与事件冒泡？”">​</a></h3><p><strong>答题要点：</strong></p><ul><li>捕获阶段：从 document → 目标元素</li><li>冒泡阶段：从目标元素 → document</li><li>可以通过 <code>addEventListener(type, handler, useCapture)</code> 控制</li></ul><h3 id="_12-什么是事件委托-优点" tabindex="-1">12. 什么是事件委托？优点？ <a class="header-anchor" href="#_12-什么是事件委托-优点" aria-label="Permalink to “12. 什么是事件委托？优点？”">​</a></h3><p><strong>答题要点：</strong></p><ul><li><p>父元素监听子元素事件，通过冒泡捕获</p></li><li><p>优点：</p><ul><li>动态元素也可绑定事件</li><li>提升性能，减少事件绑定</li></ul></li></ul><h2 id="📄-六、页面渲染与回流重绘" tabindex="-1">📄 六、页面渲染与回流重绘 <a class="header-anchor" href="#📄-六、页面渲染与回流重绘" aria-label="Permalink to “📄 六、页面渲染与回流重绘”">​</a></h2><h3 id="_13-什么是回流-reflow-与重绘-repaint" tabindex="-1">13. 什么是回流（Reflow）与重绘（Repaint）？ <a class="header-anchor" href="#_13-什么是回流-reflow-与重绘-repaint" aria-label="Permalink to “13. 什么是回流（Reflow）与重绘（Repaint）？”">​</a></h3><p><strong>答题要点：</strong></p><ul><li>回流：元素尺寸/结构/布局变化，影响后代 → 重新计算布局</li><li>重绘：样式变化但不影响布局（如颜色变）→ 重新绘制</li><li>回流性能开销 &gt; 重绘</li></ul><h3 id="_14-如何减少回流与重绘" tabindex="-1">14. 如何减少回流与重绘？ <a class="header-anchor" href="#_14-如何减少回流与重绘" aria-label="Permalink to “14. 如何减少回流与重绘？”">​</a></h3><p><strong>答题要点：</strong></p><ul><li>批量操作 DOM（如：使用 DocumentFragment）</li><li>避免逐帧操作样式（合并操作）</li><li>使用 <code>class</code> 代替 style 修改</li><li>使用 <code>requestAnimationFrame</code></li></ul><h2 id="🌐-七、跨域" tabindex="-1">🌐 七、跨域 <a class="header-anchor" href="#🌐-七、跨域" aria-label="Permalink to “🌐 七、跨域”">​</a></h2><h3 id="_15-浏览器中如何实现跨域通信" tabindex="-1">15. 浏览器中如何实现跨域通信？ <a class="header-anchor" href="#_15-浏览器中如何实现跨域通信" aria-label="Permalink to “15. 浏览器中如何实现跨域通信？”">​</a></h3><p><strong>答题要点：</strong></p><ul><li>CORS（设置响应头）</li><li>JSONP（只支持 GET）</li><li>WebSocket</li><li>postMessage</li><li>代理转发（如：前端 devServer）</li></ul><h3 id="_16-cors-的原理和流程" tabindex="-1">16. CORS 的原理和流程？ <a class="header-anchor" href="#_16-cors-的原理和流程" aria-label="Permalink to “16. CORS 的原理和流程？”">​</a></h3><p><strong>答题要点：</strong></p><ul><li>浏览器自动发送预检请求（OPTIONS）</li><li>服务端需返回响应头 <ul><li><code>Access-Control-Allow-Origin</code></li><li><code>Access-Control-Allow-Methods</code></li><li><code>Access-Control-Allow-Headers</code></li></ul></li><li>非简单请求触发预检，请求头和方法需允许</li></ul><h2 id="🧪-八、调试与开发者工具" tabindex="-1">🧪 八、调试与开发者工具 <a class="header-anchor" href="#🧪-八、调试与开发者工具" aria-label="Permalink to “🧪 八、调试与开发者工具”">​</a></h2><h3 id="_17-如何使用-devtools-进行性能分析" tabindex="-1">17. 如何使用 DevTools 进行性能分析？ <a class="header-anchor" href="#_17-如何使用-devtools-进行性能分析" aria-label="Permalink to “17. 如何使用 DevTools 进行性能分析？”">​</a></h3><p><strong>答题要点：</strong></p><ul><li><code>Performance</code> 面板：记录帧率、Layout、Paint 时间线</li><li><code>Lighthouse</code>：自动生成页面优化建议报告</li><li><code>Network</code> 面板：查看资源加载 waterfall，识别瓶颈</li><li><code>Memory</code>：分析内存泄漏、快照、GC</li></ul><h3 id="_18-如何阻止默认事件和阻止冒泡" tabindex="-1">18. 如何阻止默认事件和阻止冒泡？ <a class="header-anchor" href="#_18-如何阻止默认事件和阻止冒泡" aria-label="Permalink to “18. 如何阻止默认事件和阻止冒泡？”">​</a></h3><p><strong>答题要点：</strong></p><div class="language-js line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">js</span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">// 阻止默认行为</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">event.</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">preventDefault</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">();</span></span>
<span class="line"></span>
<span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">// 阻止冒泡</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">event.</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">stopPropagation</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">();</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br><span class="line-number">3</span><br><span class="line-number">4</span><br><span class="line-number">5</span><br></div></div><ul><li>可以结合捕获阶段精细控制事件流</li></ul><h2 id="📶-九、网络相关" tabindex="-1">📶 九、网络相关 <a class="header-anchor" href="#📶-九、网络相关" aria-label="Permalink to “📶 九、网络相关”">​</a></h2><h3 id="_19-浏览器缓存有哪些类型-它们的区别" tabindex="-1">19. 浏览器缓存有哪些类型？它们的区别？ <a class="header-anchor" href="#_19-浏览器缓存有哪些类型-它们的区别" aria-label="Permalink to “19. 浏览器缓存有哪些类型？它们的区别？”">​</a></h3><p><strong>答题要点：</strong></p><ul><li>强缓存（不发请求）：通过 <code>Cache-Control: max-age</code> 或 <code>Expires</code></li><li>协商缓存（需请求服务器）：通过 <code>ETag / If-None-Match</code> 或 <code>Last-Modified / If-Modified-Since</code></li><li>区别：强缓存命中直接使用缓存，协商缓存需询问服务端是否变更</li></ul><h3 id="_20-浏览器的重定向状态码有哪些" tabindex="-1">20. 浏览器的重定向状态码有哪些？ <a class="header-anchor" href="#_20-浏览器的重定向状态码有哪些" aria-label="Permalink to “20. 浏览器的重定向状态码有哪些？”">​</a></h3><p><strong>答题要点：</strong></p><ul><li>301：永久重定向（搜索引擎会更新链接）</li><li>302：临时重定向（原地址仍有效）</li><li>303：POST 请求重定向为 GET</li><li>307/308：保留请求方法的临时/永久跳转</li></ul><h3 id="参考链接" tabindex="-1">参考链接 <a class="header-anchor" href="#参考链接" aria-label="Permalink to “参考链接”">​</a></h3><p><a href="./../frontend/browser/basics">浏览器基础知识</a></p>`,71))])}const f=l(d,[["render",c]]);export{m as __pageData,f as default};
